6	// Receives client-side error reports from the error boundaries. Payload is
7	// size-capped and never trusted beyond logging.
8	export async function POST(req: Request) {
9	  try {
10	    const body = (await req.json().catch(() => ({}))) as {
11	      context?: string;
12	      message?: string;
13	      digest?: string;
14	      path?: string;
15	      stack?: string;
16	    };
17	    const clip = (s: unknown, n: number) => (typeof s === "string" ? s.slice(0, n) : undefined);
18	    await logError(clip(body.context, 80) ?? "client-error", { message: clip(body.message, 500), digest: clip(body.digest, 80) }, {
19	      path: clip(body.path, 200),
20	      stack: clip(body.stack, 2000),
21	      source: "client",
22	    });
23	  } catch {
24	    // ignore malformed reports
25	  }
26	  return NextResponse.json({ ok: true });
27	}
