23	async function loadServer(job: Job): Promise<Server & { plan: any; osTemplate: any; node: any }> {
24	  const server = await db.server.findUnique({
25	    where: { id: job.serverId! },
26	    include: { plan: true, osTemplate: true, node: true },
27	  });
28	  if (!server) throw new Error(`Server ${job.serverId} not found`);
29	  return server as any;
30	}
