32	/** Resolve the Proxmox client + node config for a server (falls back to the primary node). */
33	async function nodeFor(server: any) {
34	  const n =
35	    server.node ??
36	    (await db.node.findFirst({ where: { isPrimary: true } })) ??
37	    (await db.node.findFirst({ where: { enabled: true } }));
38	  if (!n) {
39	    // No Node rows yet — use the env-configured primary via the global client.
40	    return { conn: { get: pve.get, post: pve.post, put: pve.put, del: pve.del, node, waitForTask, nextVmid, vmStatus: (v: number) => pve.get(`/nodes/${node}/qemu/${v}/status/current`) } as any, row: null };
41	  }
42	  return { conn: pveFor({ apiUrl: n.apiUrl, pveNode: n.pveNode, tokenId: n.tokenId, tokenSecret: n.tokenSecret }), row: n };
43	}
