45	/** YAML-safe indent of a multi-line script under a `content: |` block. */
46	function indentBlock(text: string, spaces: number): string {
47	  const pad = " ".repeat(spaces);
48	  return text.split("\n").map((l) => pad + l).join("\n");
49	}
