51	/**
52	 * Build a per-server cloud-init vendor snippet: guest agent + root SSH,
53	 * plus any control-panel/app install script and selected add-ons. Long installs
54	 * run in the background so the VM reports ready promptly.
55	 */
56	function buildCloudInit(server: any): string {
57	  const addons = (server.addons ?? {}) as { malwareScanner?: boolean; dailyBackup?: boolean; docker?: boolean };
58	  const setup: string[] = [];
59	  if (addons.docker) setup.push("curl -fsSL https://get.docker.com | sh && systemctl enable --now docker");
60	  if (addons.malwareScanner)
61	    setup.push("(apt-get install -y clamav clamav-daemon || dnf install -y clamav) && (systemctl enable --now clamav-freshclam || true)");
62	  if (server.osTemplate.setupScript) setup.push(server.osTemplate.setupScript);
63	
64	  const script = ["#!/bin/bash", "set -x", ...setup].join("\n");
65	  return `#cloud-config
66	package_update: true
67	packages:
68	  - qemu-guest-agent
69	ssh_pwauth: true
70	disable_root: false
71	write_files:
72	  - path: /etc/ssh/sshd_config.d/60-nxeon.conf
73	    permissions: "0644"
74	    content: |
75	      PermitRootLogin yes
76	      PasswordAuthentication yes
77	  - path: /root/nxeon-setup.sh
78	    permissions: "0755"
79	    content: |
80	${indentBlock(script, 6)}
81	runcmd:
82	  - systemctl enable --now qemu-guest-agent
83	  - systemctl restart ssh || systemctl restart sshd
84	  - nohup /root/nxeon-setup.sh > /var/log/nxeon-setup.log 2>&1 &
85	`;
86	}
87	
88	const SNIPPET_DIR = process.env.NXEON_SNIPPET_DIR ?? "/tank/backup/snippets";
89	const SNIPPET_STORAGE = process.env.NXEON_SNIPPET_STORAGE ?? "backup";
90	
91	async function provision(job: Job) {
92	  const server = await loadServer(job);
93	  await db.server.update({ where: { id: server.id }, data: { status: "PROVISIONING" } });
94	
95	  const { conn, row: nodeRow } = await nodeFor(server);
96	  const storage = server.plan.storageTier === "hdd"
97	    ? nodeRow?.storageHdd ?? "vmdata-hdd"
98	    : nodeRow?.storageNvme ?? "vmdata";
99	
100	  const vmid = server.vmid ?? (await conn.nextVmid());
101	  const password = generatePassword();
102	
103	  // Dedicated public IPv4 (OVH failover + Virtual MAC on the public bridge) vs shared NAT.
104	  let dedicated: { address: string; virtualMac: string; gateway: string } | null = null;
105	  if (server.wantsDedicatedIp && ovhConfigured()) {
106	    try {
107	      dedicated = await allocateDedicatedIp(server.id, vmid);
108	    } catch (e) {
109	      console.error("[worker] dedicated IP allocation failed, falling back to NAT", e);
110	    }
111	  }
112	  const ip = dedicated ? dedicated.address : (server.ipAddress ?? (await allocateIp()));
113	  const sshPort = dedicated ? null : (server.sshPort ?? (await allocateSshPort()));
114	
115	  await db.server.update({
116	    where: { id: server.id },
117	    data: { vmid, ipAddress: ip, sshPort, rootPassword: password },
118	  });
119	
120	  const baseVmid = server.osTemplate.baseVmid ?? server.osTemplate.vmid;
121	  const cloneUpid = await conn.post(`/nodes/${conn.node}/qemu/${baseVmid}/clone`, {
122	    newid: vmid,
123	    name: server.hostname,
124	    full: 1,
125	    storage,
126	  });
127	  await conn.waitForTask(cloneUpid, 600_000);
128	
129	  // Per-server cloud-init snippet (base + panel/app install + add-ons)
130	  const snippet = buildCloudInit(server);
131	  await writeFile(`${SNIPPET_DIR}/nxeon-${vmid}.yaml`, snippet, "utf8").catch((e) =>
132	    console.error("[worker] snippet write failed", e)
133	  );
134	
135	  const keys = await db.sshKey.findMany({ where: { userId: server.userId } });
136	  const sshkeys = keys.length
137	    ? encodeURIComponent(keys.map((k) => k.publicKey.trim()).join("\n"))
138	    : undefined;
139	  const cfg: Record<string, any> = {
140	    cores: server.plan.cpuCores,
141	    memory: server.plan.ramMB,
142	    ciuser: "root",
143	    cipassword: password,
144	    sshkeys,
145	    nameserver: "1.1.1.1 8.8.8.8",
146	    onboot: 1,
147	    cicustom: `vendor=${SNIPPET_STORAGE}:snippets/nxeon-${vmid}.yaml`,
148	    tags: `${process.env.NXEON_TAG ?? "nxeon"};user-${server.userId.slice(0, 8)}`,
149	  };
150	  if (dedicated) {
151	    // Public bridge + OVH Virtual MAC; failover IP as /32 with the host's OVH gateway.
152	    cfg.net0 = `virtio=${dedicated.virtualMac},bridge=vmbr0`;
153	    cfg.ipconfig0 = `ip=${dedicated.address}/32,gw=${dedicated.gateway}`;
154	  } else {
155	    cfg.ipconfig0 = `ip=${ip}/24,gw=${gatewayIp()}`;
156	  }
157	  await conn.post(`/nodes/${conn.node}/qemu/${vmid}/config`, cfg);
158	
159	  await conn.put(`/nodes/${conn.node}/qemu/${vmid}/resize`, {
160	    disk: "scsi0",
161	    size: `${server.plan.diskGB}G`,
162	  });
163	
164	  if (!dedicated) await syncPortForwards();
165	
166	  const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/start`, {});
167	  await conn.waitForTask(startUpid);
168	
169	  await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
170	  const isImage = server.osTemplate.category !== "PLAIN_OS";
171	  const sshLine = dedicated
172	    ? `ssh root@${dedicated.address}`
173	    : `ssh root@${server.node?.publicIp ?? process.env.PUBLIC_IP} -p ${sshPort}`;
174	  await notify(
175	    server.userId,
176	    `Server ${server.hostname} is ready`,
177	    isImage ? `${server.osTemplate.name} is installing in the background (a few minutes). ${sshLine}` : sshLine,
178	    `/dashboard/servers/${server.id}`
179	  );
180	}
