182	async function powerAction(job: Job, action: "start" | "stop" | "reboot") {
183	  const server = await loadServer(job);
184	  const { conn } = await nodeFor(server);
185	  const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/${action}`, {});
186	  await conn.waitForTask(upid);
187	  await db.server.update({
188	    where: { id: server.id },
189	    data: { status: action === "stop" ? "STOPPED" : "RUNNING" },
190	  });
191	}
192	
193	async function destroyVm(conn: any, vmid: number) {
194	  // Stop first (ignore failure if already stopped), then destroy
195	  try {
196	    const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/stop`, {});
197	    await conn.waitForTask(stopUpid);
198	  } catch {
199	    /* already stopped or does not exist */
200	  }
201	  const delUpid = await conn.del(`/nodes/${conn.node}/qemu/${vmid}`, {
202	    "destroy-unreferenced-disks": 1,
203	    purge: 1,
204	  });
205	  await conn.waitForTask(delUpid, 600_000);
206	}
207	
208	async function remove(job: Job) {
209	  const server = await loadServer(job);
210	  const { conn } = await nodeFor(server);
211	  if (server.vmid) {
212	    try {
213	      await destroyVm(conn, server.vmid);
214	    } catch (e: any) {
215	      // VM may never have been created; only swallow "does not exist"
216	      if (!String(e?.body ?? e?.message).includes("does not exist")) throw e;
217	    }
218	    // Best-effort: remove the per-server cloud-init snippet
219	    await unlink(`${SNIPPET_DIR}/nxeon-${server.vmid}.yaml`).catch(() => {});
220	  }
221	  // Return any dedicated IP to the pool (deletes the OVH Virtual MAC)
222	  await releaseDedicatedIp(server.id).catch((e) => console.error("[worker] release dedicated IP failed", e));
223	  await db.server.delete({ where: { id: server.id } });
224	  await syncPortForwards();
225	}
226	
227	async function reinstall(job: Job) {
228	  const server = await loadServer(job);
229	  const { conn } = await nodeFor(server);
230	  await db.server.update({ where: { id: server.id }, data: { status: "REINSTALLING" } });
231	  if (server.vmid) await destroyVm(conn, server.vmid);
232	  await provision(job);
233	}
234	
235	async function suspend(job: Job, unsuspend: boolean) {
236	  const server = await loadServer(job);
237	  const { conn } = await nodeFor(server);
238	  if (unsuspend) {
239	    await db.server.update({ where: { id: server.id }, data: { status: "STOPPED", suspendedNote: null } });
240	    await syncPortForwards();
241	    const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
242	    await conn.waitForTask(upid);
243	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
244	  } else {
245	    try {
246	      const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/stop`, {});
247	      await conn.waitForTask(upid);
248	    } catch { /* may already be stopped */ }
249	    await db.server.update({ where: { id: server.id }, data: { status: "SUSPENDED" } });
250	    await syncPortForwards();
251	  }
252	}
253	
254	async function notify(userId: string, title: string, body?: string, href?: string) {
255	  try {
256	    await db.notification.create({ data: { userId, title, body, href } });
257	  } catch (e) {
258	    console.error("[worker] notify failed", e);
259	  }
260	}
