262	async function resize(job: Job) {
263	  const server = await loadServer(job);
264	  const payload = (job.payload ?? {}) as { planId?: string };
265	  const newPlan = await db.plan.findUnique({ where: { id: payload.planId ?? "" } });
266	  if (!newPlan) throw new Error("resize: target plan not found");
267	  if (newPlan.diskGB < server.plan.diskGB) throw new Error("resize: disk can only grow");
268	
269	  const { conn } = await nodeFor(server);
270	  const wasRunning = server.status === "RUNNING";
271	  await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
272	    cores: newPlan.cpuCores,
273	    memory: newPlan.ramMB,
274	  });
275	  if (newPlan.diskGB > server.plan.diskGB) {
276	    await conn.put(`/nodes/${conn.node}/qemu/${server.vmid}/resize`, {
277	      disk: "scsi0",
278	      size: `${newPlan.diskGB}G`,
279	    });
280	  }
281	  await db.server.update({ where: { id: server.id }, data: { planId: newPlan.id } });
282	  // CPU/RAM changes need a power cycle to apply
283	  if (wasRunning) {
284	    try {
285	      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/shutdown`, { timeout: 60 });
286	      await conn.waitForTask(stopUpid, 120_000);
287	    } catch {
288	      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/stop`, {});
289	      await conn.waitForTask(stopUpid);
290	    }
291	    const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
292	    await conn.waitForTask(startUpid);
293	  }
294	  await notify(server.userId, `Server ${server.hostname} resized to ${newPlan.name}`,
295	    `${newPlan.cpuCores} vCPU / ${newPlan.ramMB / 1024} GB RAM / ${newPlan.diskGB} GB disk`,
296	    `/dashboard/servers/${server.id}`);
