299	async function snapshotOp(job: Job, op: "create" | "delete" | "rollback") {
300	  const server = await loadServer(job);
301	  const payload = (job.payload ?? {}) as { name?: string };
302	  const name = (payload.name ?? "").replace(/[^a-zA-Z0-9_]/g, "").slice(0, 40);
303	  if (!name) throw new Error("snapshot: invalid name");
304	  const { conn } = await nodeFor(server);
305	  let upid: string;
306	  if (op === "create") {
307	    upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot`, { snapname: name });
308	  } else if (op === "delete") {
309	    upid = await conn.del(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot/${name}`);
310	  } else {
311	    upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot/${name}/rollback`, {});
312	  }
313	  await conn.waitForTask(upid, 600_000);
314	  if (op === "rollback") {
315	    // rollback leaves the VM stopped; bring it back if the server should be running
316	    const current = await db.server.findUnique({ where: { id: server.id } });
317	    if (current?.status === "RUNNING") {
318	      try {
319	        const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
320	        await conn.waitForTask(startUpid);
321	      } catch { /* may already be running */ }
322	    }
323	  }
324	}
