326	async function passwordReset(job: Job) {
327	  const server = await loadServer(job);
328	  if (!server.vmid) throw new Error("password reset: server has no VM yet");
329	  const { conn } = await nodeFor(server);
330	  const password = generatePassword();
331	
332	  // Preferred path: set it live via the qemu-guest-agent (no reboot needed).
333	  let applied = false;
334	  try {
335	    const upid = await conn.post(
336	      `/nodes/${conn.node}/qemu/${server.vmid}/agent/set-user-password`,
337	      { username: "root", password }
338	    );
339	    if (typeof upid === "string" && upid.startsWith("UPID")) await conn.waitForTask(upid);
340	    applied = true;
341	  } catch (e) {
342	    console.error("[worker] agent set-user-password failed, falling back to cloud-init", e);
343	  }
344	
345	  // Fallback: rewrite cloud-init password and reboot so it reapplies.
346	  if (!applied) {
347	    await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { cipassword: password });
348	    if (server.status === "RUNNING") {
349	      const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/reboot`, {});
350	      await conn.waitForTask(upid);
351	    }
352	  }
353	
354	  await db.server.update({ where: { id: server.id }, data: { rootPassword: password } });
355	  await notify(
356	    server.userId,
357	    `Root password reset for ${server.hostname}`,
358	    "Your new root password is available on the server's Overview tab.",
359	    `/dashboard/servers/${server.id}`
360	  );
361	}
