363	async function backupCreate(job: Job) {
364	  const server = await loadServer(job);
365	  const { conn } = await nodeFor(server);
366	  const upid = await conn.post(`/nodes/${conn.node}/vzdump`, {
367	    vmid: server.vmid,
368	    storage: "backup",
369	    mode: "snapshot",
370	    compress: "zstd",
371	  });
372	  await conn.waitForTask(upid, 3_600_000);
373	  await notify(server.userId, `Backup completed for ${server.hostname}`, undefined,
374	    `/dashboard/servers/${server.id}`);
375	}
