377	const handlers: Record<string, (job: Job) => Promise<void>> = {
378	  PROVISION: provision,
379	  START: (j) => powerAction(j, "start"),
380	  STOP: (j) => powerAction(j, "stop"),
381	  REBOOT: (j) => powerAction(j, "reboot"),
382	  DELETE: remove,
383	  REINSTALL: reinstall,
384	  SUSPEND: (j) => suspend(j, false),
385	  UNSUSPEND: (j) => suspend(j, true),
386	  RESIZE: resize,
387	  SNAPSHOT_CREATE: (j) => snapshotOp(j, "create"),
388	  SNAPSHOT_DELETE: (j) => snapshotOp(j, "delete"),
389	  SNAPSHOT_ROLLBACK: (j) => snapshotOp(j, "rollback"),
390	  BACKUP_CREATE: backupCreate,
391	  BACKUP_RESTORE: backupRestore,
392	  PASSWORD_RESET: passwordReset,
393	  SYNC_FORWARDS: async () => syncPortForwards(),
394	  GAME_UPDATE: gameUpdate,
395	};
396	
397	async function runJob(job: Job) {
398	  console.log(`[worker] job ${job.id} ${job.type} server=${job.serverId}`);
399	  await db.job.update({
400	    where: { id: job.id },
401	    data: { status: "RUNNING", attempts: { increment: 1 } },
402	  });
403	  try {
404	    await handlers[job.type](job);
405	    await db.job.update({ where: { id: job.id }, data: { status: "DONE" } });
406	    console.log(`[worker] job ${job.id} DONE`);
407	  } catch (e: any) {
408	    const error = `${e?.message ?? e}${e?.body ? ` :: ${e.body}` : ""}`.slice(0, 2000);
409	    console.error(`[worker] job ${job.id} FAILED: ${error}`);
410	    const current = await db.job.findUnique({ where: { id: job.id } });
411	    const retriable = (current?.attempts ?? MAX_ATTEMPTS) < MAX_ATTEMPTS;
412	    await db.job.update({
413	      where: { id: job.id },
414	      data: { status: retriable ? "QUEUED" : "FAILED", error },
415	    });
416	    if (!retriable && job.serverId) {
417	      const stillExists = await db.server.findUnique({ where: { id: job.serverId } });
418	      if (stillExists) {
419	        await db.server.update({ where: { id: job.serverId }, data: { status: "ERROR" } });
420	      }
421	    }
422	  }
423	}
