425	/**
426	 * Recover jobs left RUNNING by a previous worker crash/restart. Without this a
427	 * killed worker leaves a job RUNNING forever, which permanently blocks the
428	 * server's "one in-flight job" guard and strands it in a transitional state.
429	 */
430	async function reapStuckJobs() {
431	  const stuck = await db.job.findMany({ where: { status: "RUNNING" } });
432	  for (const job of stuck) {
433	    const retriable = job.attempts < MAX_ATTEMPTS;
434	    await db.job.update({
435	      where: { id: job.id },
436	      data: { status: retriable ? "QUEUED" : "FAILED", error: retriable ? null : "Worker restarted mid-job" },
437	    });
438	    if (!retriable && job.serverId) {
439	      const s = await db.server.findUnique({ where: { id: job.serverId } });
440	      if (s && ["PROVISIONING", "REINSTALLING", "DELETING"].includes(s.status)) {
441	        await db.server.update({ where: { id: job.serverId }, data: { status: "ERROR" } });
442	      }
443	    }
444	    console.log(`[worker] reaped stuck job ${job.id} (${job.type}) -> ${retriable ? "QUEUED" : "FAILED"}`);
445	  }
446	}
447	
448	async function main() {
449	  console.log("[worker] Nxeon provisioning worker starting");
450	  await reapStuckJobs();
451	  await syncPortForwards();
452	  console.log("[worker] port forwards synced");
453	
454	  let lastSweep = 0;
455	  let lastIpSync = 0;
456	  let lastGameSweep = 0;
457	  for (;;) {
458	    if (Date.now() - lastSweep > 10 * 60_000) {
459	      lastSweep = Date.now();
460	      try {
461	        await billingSweep();
462	      } catch (e) {
463	        console.error("[billing] sweep error", e);
464	      }
465	    }
466	    // Auto-update opted-in game servers every ~6h
467	    if (Date.now() - lastGameSweep > 6 * 60 * 60_000) {
468	      lastGameSweep = Date.now();
469	      try {
470	        await gameUpdateSweep();
471	      } catch (e) {
472	        console.error("[game-update] sweep error", e);
473	      }
474	    }
475	    // Pull newly-delivered OVH IPs into the pool every 5 min
476	    if (ovhConfigured() && Date.now() - lastIpSync > 5 * 60_000) {
477	      lastIpSync = Date.now();
478	      try {
479	        const r = await syncDedicatedIpPool();
480	        if (r.imported > 0) console.log(`[worker] dedicated IP pool: imported ${r.imported}, total ${r.total}`);
481	      } catch (e) {
482	        console.error("[worker] IP pool sync error", e);
483	      }
484	    }
485	    try {
486	      const job = await db.job.findFirst({
487	        where: { status: "QUEUED" },
488	        orderBy: { createdAt: "asc" },
489	      });
490	      if (job) {
491	        await runJob(job);
492	      } else {
493	        await new Promise((r) => setTimeout(r, POLL_MS));
494	      }
495	    } catch (e) {
496	      console.error("[worker] loop error", e);
497	      await new Promise((r) => setTimeout(r, POLL_MS));
498	    }
499	  }
500	}
501	
502	main();
