import { db } from "@/lib/db";

/**
 * Plain (non-action) aggregation helpers for the visitor-analytics admin page.
 * These are read-only Prisma queries over the `Visit` table. Everything is
 * scoped to short recent windows and small `take` limits so the page stays
 * cheap even as the visit log grows.
 */

const DAY = 86_400_000;

/** Distinct client IPs seen in the last `minutes` — our "live visitors now" gauge. */
export async function liveVisitors(minutes = 5): Promise<number> {
  const since = new Date(Date.now() - minutes * 60_000);
  const rows = await db.visit.findMany({
    where: { createdAt: { gte: since } },
    distinct: ["ip"],
    select: { ip: true },
  });
  return rows.length;
}

/** Total page views since local midnight. */
export async function todayViews(): Promise<number> {
  const start = new Date();
  start.setHours(0, 0, 0, 0);
  return db.visit.count({ where: { createdAt: { gte: start } } });
}

/** Total page views in the trailing `days` window (default 7d). */
export async function viewsInWindow(days = 7): Promise<number> {
  const since = new Date(Date.now() - days * DAY);
  return db.visit.count({ where: { createdAt: { gte: since } } });
}

/** Distinct visitors (by IP) in the trailing `days` window. */
export async function uniqueVisitors(days = 7): Promise<number> {
  const since = new Date(Date.now() - days * DAY);
  const rows = await db.visit.findMany({
    where: { createdAt: { gte: since } },
    distinct: ["ip"],
    select: { ip: true },
  });
  return rows.length;
}

/** Reduce a raw referrer URL to a bare hostname for grouping/display. */
export function referrerHost(ref: string | null | undefined): string | null {
  if (!ref) return null;
  try {
    const h = new URL(ref).hostname.replace(/^www\./, "");
    return h || null;
  } catch {
    const trimmed = ref.trim();
    return trimmed ? trimmed.slice(0, 60) : null;
  }
}

export type Counted = { label: string; count: number };

/** Top external referrer hosts over the trailing `days` window. */
export async function topReferrers(days = 7, limit = 8): Promise<Counted[]> {
  const since = new Date(Date.now() - days * DAY);
  const rows = await db.visit.findMany({
    where: { createdAt: { gte: since }, referrer: { not: null } },
    select: { referrer: true },
    take: 5000,
    orderBy: { createdAt: "desc" },
  });
  const tally = new Map<string, number>();
  for (const r of rows) {
    const host = referrerHost(r.referrer);
    if (!host) continue;
    tally.set(host, (tally.get(host) ?? 0) + 1);
  }
  return [...tally.entries()]
    .map(([label, count]) => ({ label, count }))
    .sort((a, b) => b.count - a.count)
    .slice(0, limit);
}

/** Top countries among geocoded visits over the trailing `days` window. */
export async function topCountries(days = 30, limit = 8): Promise<Counted[]> {
  const since = new Date(Date.now() - days * DAY);
  const grp = await db.visit.groupBy({
    by: ["country"],
    where: { createdAt: { gte: since }, geocoded: true, country: { not: null } },
    _count: { _all: true },
  });
  return grp
    .map((g) => ({ label: g.country as string, count: g._count._all }))
    .sort((a, b) => b.count - a.count)
    .slice(0, limit);
}

/** Top cities among geocoded visits over the trailing `days` window. */
export async function topCities(days = 30, limit = 8): Promise<Counted[]> {
  const since = new Date(Date.now() - days * DAY);
  const rows = await db.visit.findMany({
    where: { createdAt: { gte: since }, geocoded: true, city: { not: null } },
    select: { city: true, country: true },
    take: 5000,
    orderBy: { createdAt: "desc" },
  });
  const tally = new Map<string, number>();
  for (const r of rows) {
    const label = r.country ? `${r.city}, ${r.country}` : (r.city as string);
    tally.set(label, (tally.get(label) ?? 0) + 1);
  }
  return [...tally.entries()]
    .map(([label, count]) => ({ label, count }))
    .sort((a, b) => b.count - a.count)
    .slice(0, limit);
}

export type RecentVisit = {
  id: string;
  ip: string;
  path: string;
  referrer: string | null;
  kind: string;
  country: string | null;
  region: string | null;
  city: string | null;
  createdAt: Date;
};

/** Most recent visits for the live activity table. */
export async function recentVisits(limit = 40): Promise<RecentVisit[]> {
  return db.visit.findMany({
    orderBy: { createdAt: "desc" },
    take: limit,
    select: {
      id: true,
      ip: true,
      path: true,
      referrer: true,
      kind: true,
      country: true,
      region: true,
      city: true,
      createdAt: true,
    },
  });
}

export type GlobePoint = {
  lat: number;
  lng: number;
  city: string | null;
  country: string | null;
  kind: string;
};

/**
 * Recent geocoded visits with coordinates, for the activity globe. Capped so the
 * canvas stays performant regardless of how much traffic has accumulated.
 */
export async function globePoints(days = 7, limit = 300): Promise<GlobePoint[]> {
  const since = new Date(Date.now() - days * DAY);
  const rows = await db.visit.findMany({
    where: {
      createdAt: { gte: since },
      geocoded: true,
      lat: { not: null },
      lng: { not: null },
    },
    orderBy: { createdAt: "desc" },
    take: limit,
    select: { lat: true, lng: true, city: true, country: true, kind: true },
  });
  return rows.map((r) => ({
    lat: r.lat as number,
    lng: r.lng as number,
    city: r.city,
    country: r.country,
    kind: r.kind,
  }));
}

import { NextResponse } from "next/server";
import { db } from "@/lib/db";

export const runtime = "nodejs";

/**
 * Page-view capture endpoint. Called fire-and-forget by <VisitTracker/> mounted
 * in the marketing layout and the portal Shell. It records a single `Visit` row
 * and MUST NOT throw or block the caller — analytics is strictly best-effort.
 *
 * The client IP is taken only from `x-forwarded-for` (nginx sets it); we never
 * trust a body-supplied IP. Bots are dropped by a coarse UA check. The visit
 * "kind" (marketing vs portal) comes from a `?k=` query param the mounter sets.
 */

const BOT_RE =
  /bot|crawl|spider|slurp|bingpreview|mediapartners|adsbot|facebookexternalhit|embedly|quora|pinterest|redditbot|whatsapp|telegrambot|discordbot|slackbot|semrush|ahrefs|mj12|dotbot|petalbot|yandex|baidu|duckduckbot|headless|phantomjs|python-requests|python-urllib|go-http|libwww|curl\/|wget\/|okhttp|axios\/|node-fetch|lighthouse|pagespeed|gtmetrix|pingdom|uptimerobot|statuscake|monitor|preview|scrapy/i;

/** First hop of x-forwarded-for is the real client (nginx appends downstream). */
function clientIp(req: Request): string {
  const xff = req.headers.get("x-forwarded-for") ?? "";
  const first = xff.split(",")[0]?.trim();
  return first || "unknown";
}

export async function POST(req: Request) {
  try {
    const url = new URL(req.url);
    const kindParam = url.searchParams.get("k");
    const kind = kindParam === "portal" ? "portal" : "marketing";

    const ua = (req.headers.get("user-agent") ?? "").slice(0, 400);
    // Silently accept but skip obvious bots and empty UAs.
    if (!ua || BOT_RE.test(ua)) {
      return NextResponse.json({ ok: true });
    }

    const body = (await req.json().catch(() => ({}))) as {
      path?: unknown;
      referrer?: unknown;
    };
    const path =
      typeof body.path === "string" && body.path ? body.path.slice(0, 300) : "/";
    let referrer =
      typeof body.referrer === "string" && body.referrer
        ? body.referrer.slice(0, 400)
        : null;
    // Drop same-origin referrers — they're just internal navigation noise.
    if (referrer) {
      try {
        if (new URL(referrer).host === url.host) referrer = null;
      } catch {
        /* keep opaque referrer strings as-is */
      }
    }

    await db.visit.create({
      data: { ip: clientIp(req), path, referrer, ua, kind },
    });
  } catch {
    // Never surface capture failures to the page.
  }
  return NextResponse.json({ ok: true });
}

"use client";

import { useEffect } from "react";
import { usePathname } from "next/navigation";

/**
 * Invisible page-view beacon. Mount once in the marketing layout (kind default)
 * and once in the portal Shell with `kind="portal"`. On every client-side route
 * change it fires a best-effort POST to /api/track. Rapid repeats of the same
 * path are de-duped within the tab via sessionStorage so React strict-mode
 * double-mounts and quick back/forward navigation don't double-count.
 */
export default function VisitTracker({ kind = "marketing" }: { kind?: "marketing" | "portal" }) {
  const pathname = usePathname();

  useEffect(() => {
    if (typeof window === "undefined") return;
    const path = pathname || window.location.pathname || "/";

    // Dedupe: skip if we already tracked this exact path within the last 30s.
    const key = `nx_track:${kind}:${path}`;
    try {
      const last = Number(window.sessionStorage.getItem(key) ?? 0);
      if (Date.now() - last < 30_000) return;
      window.sessionStorage.setItem(key, String(Date.now()));
    } catch {
      /* private mode / storage disabled — just proceed without dedupe */
    }

    try {
      fetch(`/api/track?k=${kind}`, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ path, referrer: document.referrer || null }),
        keepalive: true,
      }).catch(() => {});
    } catch {
      /* fire-and-forget; never disrupt the page */
    }
  }, [pathname, kind]);

  return null;
}

import { db } from "../lib/db";

/**
 * Best-effort geo-enrichment of captured visits. Called periodically from the
 * worker loop. For each recent visit still marked `geocoded=false` we resolve
 * its IP to a coarse location — first from the local `GeoCache`, else via the
 * free, keyless ip-api.com endpoint — then copy the location onto the visit and
 * flip `geocoded=true`.
 *
 * Design constraints:
 *  - No API key, so we respect ip-api's free tier (~45 req/min) by capping the
 *    number of *external* lookups per sweep and pacing them.
 *  - Private / non-routable IPs are skipped (marked geocoded with no location).
 *  - Every network/DB op is defensive: one failure never aborts the sweep.
 */

const MAX_EXTERNAL_PER_SWEEP = 40; // stay under ip-api's 45/min free limit
const PACE_MS = 1500; // spacing between external calls
const BATCH = 200; // how many pending visits to consider per sweep

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

type Geo = {
  country: string | null;
  region: string | null;
  city: string | null;
  lat: number | null;
  lng: number | null;
};

const EMPTY: Geo = { country: null, region: null, city: null, lat: null, lng: null };

/** True for private, loopback, link-local or otherwise non-geolocatable addresses. */
function isPrivateIp(ip: string): boolean {
  if (!ip || ip === "unknown") return true;
  if (ip === "::1" || ip === "127.0.0.1" || ip.startsWith("127.")) return true;
  if (ip.startsWith("10.")) return true;
  if (ip.startsWith("192.168.")) return true;
  if (ip.startsWith("169.254.")) return true; // link-local
  // 172.16.0.0 – 172.31.255.255
  const m = ip.match(/^172\.(\d+)\./);
  if (m) {
    const second = Number(m[1]);
    if (second >= 16 && second <= 31) return true;
  }
  // IPv6 unique-local / link-local
  const low = ip.toLowerCase();
  if (low.startsWith("fc") || low.startsWith("fd") || low.startsWith("fe80")) return true;
  return false;
}

/** Look up an IP via ip-api.com. Returns null on any failure. */
async function fetchGeo(ip: string): Promise<Geo | null> {
  try {
    const res = await fetch(
      `http://ip-api.com/json/${encodeURIComponent(ip)}?fields=status,country,regionName,city,lat,lon`,
      { signal: AbortSignal.timeout(6000) }
    );
    if (!res.ok) return null;
    const data = (await res.json()) as {
      status?: string;
      country?: string;
      regionName?: string;
      city?: string;
      lat?: number;
      lon?: number;
    };
    if (data.status !== "success") return null;
    return {
      country: data.country ?? null,
      region: data.regionName ?? null,
      city: data.city ?? null,
      lat: typeof data.lat === "number" ? data.lat : null,
      lng: typeof data.lon === "number" ? data.lon : null,
    };
  } catch {
    return null;
  }
}

export async function geoEnrichSweep(): Promise<{ processed: number; external: number }> {
  let processed = 0;
  let external = 0;

  let pending: { id: string; ip: string }[] = [];
  try {
    pending = await db.visit.findMany({
      where: { geocoded: false },
      orderBy: { createdAt: "desc" },
      take: BATCH,
      select: { id: true, ip: true },
    });
  } catch (e) {
    console.error("[geo] failed to load pending visits", e);
    return { processed, external };
  }

  // Resolve one IP at a time, sharing results across visits from the same IP
  // within this sweep so a burst from one client costs a single lookup.
  const resolved = new Map<string, Geo>();

  for (const visit of pending) {
    try {
      const ip = visit.ip;
      let geo = resolved.get(ip);

      if (!geo) {
        if (isPrivateIp(ip)) {
          geo = EMPTY;
        } else {
          // 1) local cache
          const cached = await db.geoCache.findUnique({ where: { ip } }).catch(() => null);
          if (cached) {
            geo = {
              country: cached.country,
              region: cached.region,
              city: cached.city,
              lat: cached.lat,
              lng: cached.lng,
            };
          } else if (external < MAX_EXTERNAL_PER_SWEEP) {
            // 2) external lookup (rate-limited)
            if (external > 0) await sleep(PACE_MS);
            external++;
            const fetched = await fetchGeo(ip);
            if (fetched) {
              geo = fetched;
              await db.geoCache
                .upsert({
                  where: { ip },
                  create: { ip, ...fetched },
                  update: { ...fetched },
                })
                .catch((e) => console.error("[geo] cache upsert failed", e));
            } else {
              // Lookup failed this round — leave the visit for a later sweep.
              continue;
            }
          } else {
            // Hit the per-sweep external budget; defer remaining IPs.
            continue;
          }
        }
        resolved.set(ip, geo);
      }

      await db.visit.update({
        where: { id: visit.id },
        data: {
          country: geo.country,
          region: geo.region,
          city: geo.city,
          lat: geo.lat,
          lng: geo.lng,
          geocoded: true,
        },
      });
      processed++;
    } catch (e) {
      console.error("[geo] failed to enrich visit", visit.id, e);
    }
  }

  if (processed > 0) {
    console.log(`[geo] enriched ${processed} visit(s) (${external} external lookups)`);
  }
  return { processed, external };
}

"use client";

import { useEffect, useRef } from "react";

/**
 * Self-contained activity globe. No external libraries — it's a canvas-2D
 * orthographic projection of a sphere with a lat/lng graticule, auto-rotation,
 * and glowing pulsing dots at each visit's coordinates. Only the front-facing
 * hemisphere is drawn (points behind the sphere are hidden), which sells the 3D
 * read cheaply. Honors `prefers-reduced-motion` by holding a static frame.
 */

export type GlobePoint = {
  lat: number;
  lng: number;
  city: string | null;
  country: string | null;
  kind: string;
};

const DEG = Math.PI / 180;

export default function VisitorGlobe({ points }: { points: GlobePoint[] }) {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduced =
      typeof window !== "undefined" &&
      window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;

    let raf = 0;
    let disposed = false;

    // Logical drawing size; backing store scaled for crisp HiDPI.
    const SIZE = 460;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = SIZE * dpr;
    canvas.height = SIZE * dpr;
    ctx.scale(dpr, dpr);

    const cx = SIZE / 2;
    const cy = SIZE / 2;
    const R = SIZE / 2 - 24;

    // Precompute point unit vectors (in a globe frame where lng 0 faces camera
    // at rotation 0). We rotate around the Y (vertical) axis over time.
    const pts = points.map((p) => {
      const lat = p.lat * DEG;
      const lng = p.lng * DEG;
      return {
        x: Math.cos(lat) * Math.sin(lng),
        y: Math.sin(lat),
        z: Math.cos(lat) * Math.cos(lng),
        seed: Math.random() * Math.PI * 2,
        kind: p.kind,
      };
    });

    function project(x: number, y: number, z: number, rot: number) {
      // rotate around vertical (Y) axis
      const sinR = Math.sin(rot);
      const cosR = Math.cos(rot);
      const rx = x * cosR - z * sinR;
      const rz = x * sinR + z * cosR;
      return { sx: cx + rx * R, sy: cy - y * R, depth: rz };
    }

    function draw(t: number) {
      if (disposed) return;
      const rot = reduced ? -0.5 : t * 0.00018;
      ctx!.clearRect(0, 0, SIZE, SIZE);

      // Sphere body with a soft radial shade for volume.
      const grad = ctx!.createRadialGradient(cx - R * 0.35, cy - R * 0.4, R * 0.15, cx, cy, R);
      grad.addColorStop(0, "rgba(59,130,246,0.22)");
      grad.addColorStop(0.55, "rgba(40,30,90,0.35)");
      grad.addColorStop(1, "rgba(10,8,25,0.55)");
      ctx!.beginPath();
      ctx!.arc(cx, cy, R, 0, Math.PI * 2);
      ctx!.fillStyle = grad;
      ctx!.fill();

      // Rim light.
      ctx!.beginPath();
      ctx!.arc(cx, cy, R, 0, Math.PI * 2);
      ctx!.lineWidth = 1.2;
      ctx!.strokeStyle = "rgba(138,112,251,0.45)";
      ctx!.stroke();

      // Graticule — latitude rings + longitude meridians on the front hemisphere.
      ctx!.strokeStyle = "rgba(255,255,255,0.06)";
      ctx!.lineWidth = 1;
      for (let latD = -60; latD <= 60; latD += 30) {
        const lat = latD * DEG;
        ctx!.beginPath();
        let started = false;
        for (let lngD = -180; lngD <= 180; lngD += 6) {
          const lng = lngD * DEG;
          const x = Math.cos(lat) * Math.sin(lng);
          const y = Math.sin(lat);
          const z = Math.cos(lat) * Math.cos(lng);
          const pr = project(x, y, z, rot);
          if (pr.depth < 0) {
            started = false;
            continue;
          }
          if (!started) {
            ctx!.moveTo(pr.sx, pr.sy);
            started = true;
          } else ctx!.lineTo(pr.sx, pr.sy);
        }
        ctx!.stroke();
      }
      for (let lngD = 0; lngD < 180; lngD += 30) {
        const lng = lngD * DEG;
        ctx!.beginPath();
        let started = false;
        for (let latD = -90; latD <= 90; latD += 4) {
          const lat = latD * DEG;
          const x = Math.cos(lat) * Math.sin(lng);
          const y = Math.sin(lat);
          const z = Math.cos(lat) * Math.cos(lng);
          const pr = project(x, y, z, rot);
          if (pr.depth < 0) {
            started = false;
            continue;
          }
          if (!started) {
            ctx!.moveTo(pr.sx, pr.sy);
            started = true;
          } else ctx!.lineTo(pr.sx, pr.sy);
        }
        ctx!.stroke();
      }

      // Visit dots — only the front hemisphere, with a time-based pulse.
      for (const p of pts) {
        const pr = project(p.x, p.y, p.z, rot);
        if (pr.depth < 0) continue; // behind the globe
        const portal = p.kind === "portal";
        const core = portal ? "138,112,251" : "52,211,153"; // brand purple vs emerald
        const pulse = reduced ? 0.6 : 0.5 + 0.5 * Math.sin(t * 0.004 + p.seed);
        const edgeFade = 0.35 + 0.65 * pr.depth; // dim near the limb

        // glow
        ctx!.beginPath();
        ctx!.arc(pr.sx, pr.sy, 6 + pulse * 5, 0, Math.PI * 2);
        ctx!.fillStyle = `rgba(${core},${0.12 * edgeFade})`;
        ctx!.fill();
        // core
        ctx!.beginPath();
        ctx!.arc(pr.sx, pr.sy, 2.2, 0, Math.PI * 2);
        ctx!.fillStyle = `rgba(${core},${(0.75 + 0.25 * pulse) * edgeFade})`;
        ctx!.fill();
      }

      if (!reduced) raf = requestAnimationFrame(draw);
    }

    if (reduced) draw(0);
    else raf = requestAnimationFrame(draw);

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
    };
  }, [points]);

  return (
    <div className="card flex flex-col items-center justify-center overflow-hidden p-4">
      <div className="mb-2 flex w-full items-center justify-between">
        <h2 className="font-semibold">Live activity globe</h2>
        <span className="text-xs text-slate-500">{points.length} recent</span>
      </div>
      <div className="relative">
        <canvas
          ref={canvasRef}
          style={{ width: 460, height: 460, maxWidth: "100%" }}
          aria-label="Rotating globe plotting recent visitor locations"
          role="img"
        />
      </div>
      <div className="mt-2 flex items-center gap-4 text-xs text-slate-400">
        <span className="inline-flex items-center gap-1.5">
          <span className="h-2 w-2 rounded-full" style={{ background: "#34d399" }} /> marketing
        </span>
        <span className="inline-flex items-center gap-1.5">
          <span className="h-2 w-2 rounded-full" style={{ background: "#8a70fb" }} /> portal
        </span>
      </div>
      {points.length === 0 && (
        <p className="mt-3 max-w-xs text-center text-xs text-slate-500">
          No geocoded visits yet — dots appear here as the worker resolves visitor locations.
        </p>
      )}
    </div>
  );
}

import { Badge, timeAgo } from "@/components/ui/primitives";
import type { Counted, RecentVisit } from "@/lib/analytics";
import { referrerHost } from "@/lib/analytics";

/** A compact ranked list ("top referrers", "top countries", …) with count bars. */
export function RankedList({
  title,
  sub,
  items,
  emptyLabel,
}: {
  title: string;
  sub?: string;
  items: Counted[];
  emptyLabel: string;
}) {
  const max = items.reduce((m, i) => Math.max(m, i.count), 0) || 1;
  return (
    <div className="card">
      <h2 className="font-semibold">{title}</h2>
      {sub && <p className="mt-1 text-xs text-slate-500">{sub}</p>}
      {items.length === 0 ? (
        <p className="py-6 text-sm text-slate-500">{emptyLabel}</p>
      ) : (
        <ul className="mt-3 space-y-2.5">
          {items.map((it) => (
            <li key={it.label}>
              <div className="flex items-center justify-between text-sm">
                <span className="truncate pr-3 text-slate-200">{it.label}</span>
                <span className="tabular-nums text-slate-400">{it.count}</span>
              </div>
              <div className="mt-1 h-1.5 overflow-hidden rounded-full bg-white/[0.05]">
                <div
                  className="h-full rounded-full bg-gradient-to-r from-accent-blue to-brand-500"
                  style={{ width: `${Math.max(6, (it.count / max) * 100)}%` }}
                />
              </div>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

function geoLabel(v: RecentVisit): string {
  const parts = [v.city, v.region, v.country].filter(Boolean);
  return parts.length ? parts.join(", ") : "—";
}

/** The live recent-visits table (time / IP / geo / path / referrer / kind). */
export function RecentVisitsTable({ visits }: { visits: RecentVisit[] }) {
  return (
    <div className="card p-0">
      <div className="px-5 pt-5">
        <h2 className="font-semibold">Recent visits</h2>
        <p className="mt-1 text-xs text-slate-500">
          Newest page views across the marketing site and the customer/admin portals.
        </p>
      </div>
      {visits.length === 0 ? (
        <p className="px-5 py-8 text-sm text-slate-500">
          No visits captured yet. Views appear here in real time once the tracker is mounted.
        </p>
      ) : (
        <div className="overflow-x-auto pt-3">
          <table className="table-shell">
            <thead>
              <tr>
                <th>When</th>
                <th>IP</th>
                <th>Location</th>
                <th>Path</th>
                <th>Referrer</th>
                <th>Source</th>
              </tr>
            </thead>
            <tbody>
              {visits.map((v) => {
                const ref = referrerHost(v.referrer);
                return (
                  <tr key={v.id}>
                    <td className="whitespace-nowrap text-slate-400">{timeAgo(v.createdAt)}</td>
                    <td className="whitespace-nowrap font-mono text-xs text-slate-400">{v.ip}</td>
                    <td className="whitespace-nowrap text-slate-300">{geoLabel(v)}</td>
                    <td className="max-w-[220px] truncate font-mono text-xs text-slate-200" title={v.path}>
                      {v.path}
                    </td>
                    <td className="max-w-[160px] truncate text-slate-400" title={v.referrer ?? ""}>
                      {ref ?? <span className="text-slate-600">direct</span>}
                    </td>
                    <td>
                      <Badge tone={v.kind === "portal" ? "brand" : "slate"}>{v.kind}</Badge>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}
